import pandas as pd,re
bounds=dict(O=.697674,Cu=.454545,Ba=.333333,Sr=.285714,Y=.4,Ca=.272727,La=.78,Bi=.521978,Fe=.502513,Nb=.98,C=.972,Pr=.265043,As=.5,B=1,Pb=.5,Ce=.28,Mo=1,V=.9918,Zn=1,Ni=.6)
rows=[]
for _,r in pd.read_csv('b3_supercon_data.csv').iterrows():
    amounts={}
    for e,v in re.findall(r'([A-Z][a-z]*)([0-9]*\.?[0-9]*)',r.composition):
        amounts[e]=amounts.get(e,0)+float(v or 1)
    tot=sum(amounts.values()); f={e:v/tot for e,v in amounts.items()}
    if len(f)<=4 and all(e in bounds and v<=bounds[e]+1e-12 for e,v in f.items()):
        rows.append((r.target,r.composition,f))
for tc,c,f in sorted(rows,reverse=True)[:10]: print(tc,c,f)
print('Feasible rows:',len(rows))
